using namespace std;

class GraphPath {
    int N;
    vector<vector<pair<int, int>>> adj;
public:
    GraphPath(int n) : N(n), adj(n + 1) {}
    void addEdge(int u, int v, int w) { adj[u].push_back({v, w}); }
    vector<int> getShortestDistances(int start, int end) {
        vector<int> dist(N + 1, INT_MAX);
        dist[start] = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, start});
        while (!pq.empty()) {
            int w = -pq.top().first;
            int u = pq.top().second;
            pq.pop();
            if (u == end) return dist;
            if (dist[u] < w) continue;
            for (auto &edge : adj[u]) {
                int v = edge.first, w2 = w + edge.second;
                if (dist[v] > w2) {
                    dist[v] = w2;
                    pq.push({-w2, v});
                }
            }
        }
        return dist;
    }
    void run() {
        int n, e, s, u, v, w;
        scanf("%d%d", &n, &e);
        GraphPath gp(n);
        scanf("%d", &s);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            gp.addEdge(u, v, w);
        }
        vector<int> ans = gp.getShortestDistances(s, N);
        for (int i = 1; i <= n; i++) {
            if (ans[i] >= INT_MAX) printf("INF\n");
            else printf("%d\n", ans[i]);
        }
    }
};

class GraphMST {
    int N;
    vector<vector<pair<int, int>>> edges;
public:
    GraphMST(int n) : N(n), edges(n + 1) {}
    void insert(int u, int v, int w) { edges[u].push_back({v, w}); }
    void computeMinimumSpanningTree(long long &totalCost) {
        vector<int> dist(N + 1, INT_MAX);
        vector<bool> inMST(N + 1, false);
        dist[1] = 0;
        totalCost = 0;
        priority_queue<pair<int, int>> pq;
        pq.push({0, 1});
        for (int i = 0; i < N; i++) {
            int u = -1, minDist = INT_MAX;
            while (!pq.empty()) {
                u = pq.top().second;
                pq.pop();
                if (!inMST[u]) break;
            }
            if (u == -1 || inMST[u]) break;
            inMST[u] = true;
            totalCost += dist[u];
            for (auto &edge : edges[u]) {
                int v = edge.first, w = edge.second;
                if (!inMST[v] && dist[v] > w) {
                    dist[v] = w;
                    pq.push({-w, v});
                }
            }
        }
    }
    void run() {
        int n, e, u, v, w;
        scanf("%d%d", &n, &e);
        GraphMST gm(n);
        for (int i = 0; i < e; i++) {
            scanf("%d%d%d", &u, &v, &w);
            gm.insert(u, v, w);
        }
        long long total = 0;
        gm.computeMinimumSpanningTree(total);
        printf("%lld", total);
    }
};

